#include <iostream>
#include <iomanip>
#include <cstdint>

void displayMemorySegment(const void* startAddress, std::size_t byteCount) {
    const auto* bytePtr = reinterpret_cast<const std::uint8_t*>(startAddress);
    for (std::size_t offset = 0; offset < byteCount; ++offset) {
        std::cout << "Offset +" << offset
                  << " | Char: '" << static_cast<char>(bytePtr[offset]) << "'"
                  << " | Hex: 0x" << std::hex << std::uppercase << std::setw(2)
                  << std::setfill('0') << static_cast<int>(bytePtr[offset])
                  << std::dec << "\n";
    }
}

int main() {
    // Replicating Figure 1.3: character encoding sequence 'C', 'r', 'e', 'w', and 3
    char memoryBuffer[5] = {'C', 'r', 'e', 'w', 3};
    std::cout << "Simulating RAM sequential byte contents (Figure 1.3):\n";
    displayMemorySegment(memoryBuffer, sizeof(memoryBuffer));
    return 0;
}

#include <iostream>
#include <string_view>
#include <cstdint>

struct MediaSpec {
    std::string_view name;
    std::uint64_t capacityMB;
};

int main() {
    constexpr std::uint64_t docSizeKB = 20;
    constexpr std::uint64_t movieSizeMB = 8 * 1000; // 8 GB = 8000 MB

    const MediaSpec mediaList[] = {
        {"Standard CD-R/RW (700 MB)", 700},
        {"Standard DVD-R/RW (4.7 GB)", 4700},
        {"USB Flash Drive (256 GB)", 256000},
        {"Hard Disk Drive (800 GB)", 800000}
    };

    std::cout << "Storage Capacity Calculations (20 KB/doc, 8 GB/movie):\n";
    for (const auto& item : mediaList) {
        std::uint64_t docCount = (item.capacityMB * 1000) / docSizeKB;
        std::uint64_t movieCount = item.capacityMB / movieSizeMB;
        std::cout << item.name << ": " 
                  << docCount << " pages | " 
                  << movieCount << " movies\n";
    }
    return 0;
}

#include <iostream>
#include <string_view>
#include <iomanip>

struct SystemComponent {
    std::string_view category;
    std::string_view component;
    std::string_view specification;
};

int main() {
    const SystemComponent systemSpecs[] = {
        {"Core Hardware", "Central Processing Unit (CPU)", "3.2 GHz Clock Rate"},
        {"Core Hardware", "Random-Access Memory (RAM)", "8 GB Volatile (MB/GB)"},
        {"Storage Device", "Hard Disk Drive (HDD)", "500 GB Non-volatile (GB/TB)"},
        {"Storage Device", "CD-RW / DVD-RW", "700 MB / 4.7 GB Optical"},
        {"Storage Device", "USB Flash Drive", "64 GB Solid State"},
        {"Input Device", "Keyboard & Mouse", "USB interface, Modifier keys"},
        {"Output Device", "Monitor & Laser Printer", "1024x768 Res, 0.25mm Pitch"},
        {"Communication", "1000BaseT NIC & Wireless", "1,000 mbps LAN / 802.11"}
    };

    std::cout << std::left << std::setw(17) << "Category"
              << std::setw(32) << "Component"
              << "Specification\n";
    std::cout << std::string(75, '-') << "\n";

    for (const auto& item : systemSpecs) {
        std::cout << std::left << std::setw(17) << item.category
                  << std::setw(32) << item.component
                  << item.specification << "\n";
    }
    return 0;
}
